@test
def set_get_roundtrip(c):
    k = K("sg")
    eq(c.cmd("SET", k, "bar"), ("simple", b"OK"))
    eq(c.cmd("GET", k), ("bulk", b"bar"))


@test
def get_missing_is_nil(c):
